'use client'

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { supabase } from '@/lib/supabase'

// ============================================
// TYPES
// ============================================

export interface Block {
    id: string
    type: 'text' | 'image' | 'imageGrid' | 'color' | 'typography' | 'divider' | 'embed' | 'file' | 'colorPalette' | 'spacer' | 'button'
    content: any
}

export interface BrandSection {
    id: string
    slug: string
    title: string
    group?: string
    blocks: Block[]
}

export interface BrandDraft {
    sections: BrandSection[]
}

export interface BrandMetadata {
    id: string
    name: string
    slug: string
    logo_url: string | null
    banner_url: string | null
    primary_color: string | null
    font_family: string | null
    custom_font_url: string | null
}

interface UseBrandEditorReturn {
    sections: BrandSection[]
    setSections: (sections: BrandSection[]) => void
    loading: boolean
    error: string | null
    brandMetadata: BrandMetadata | null
    isDirty: boolean

    // Actions
    updateBlock: (sectionId: string, blockId: string, content: any) => void
    addBlock: (sectionId: string, block: Block, afterBlockId?: string) => void
    deleteBlock: (sectionId: string, blockId: string) => void
    moveBlock: (sectionId: string, blockId: string, direction: 'up' | 'down') => void
    reorderBlocks: (sectionId: string, oldIndex: number, newIndex: number) => void

    addSection: (section: BrandSection) => void
    updateSection: (sectionId: string, updates: Partial<BrandSection>) => void
    deleteSection: (sectionId: string) => void
    reorderSections: (sectionIds: string[]) => void

    saveDraft: () => Promise<{ error: Error | null }>
    publish: () => Promise<{ error: Error | null }>

    undo: () => void
    redo: () => void
    canUndo: boolean
    canRedo: boolean

    // Backwards compatibility for BrandCanvas
    draft: { sections: BrandSection[] }
    saving: boolean
    removeBlock: (sectionId: string, blockIndex: number) => void
    removeSection: (sectionId: string) => void
    updateBrandMetadata: (updates: any) => Promise<void>
}

// ============================================
// SIMPLE CACHE
// ============================================
const cache = new Map<string, { data: any; timestamp: number }>()
const CACHE_TTL = 60 * 1000 // 1 minute

function getCached<T>(key: string): T | null {
    const entry = cache.get(key)
    if (entry && Date.now() - entry.timestamp < CACHE_TTL) {
        return entry.data as T
    }
    return null
}

function setCache(key: string, data: any) {
    cache.set(key, { data, timestamp: Date.now() })
}

// ============================================
// HOOK
// ============================================

export function useBrandEditor(identifier: string): UseBrandEditorReturn {
    const [sections, setSectionsInternal] = useState<BrandSection[]>([])
    const [brandMetadata, setBrandMetadata] = useState<BrandMetadata | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)
    const [isDirty, setIsDirty] = useState(false)

    // History for undo/redo
    const [history, setHistory] = useState<BrandSection[][]>([])
    const [historyIndex, setHistoryIndex] = useState(-1)
    const skipHistoryRef = useRef(false)

    const canUndo = historyIndex > 0
    const canRedo = historyIndex < history.length - 1

    // ============================================
    // SET SECTIONS WITH HISTORY
    // ============================================
    const setSections = useCallback((newSections: BrandSection[]) => {
        setSectionsInternal(newSections)
        setIsDirty(true)

        if (!skipHistoryRef.current) {
            setHistory(prev => [...prev.slice(0, historyIndex + 1), newSections])
            setHistoryIndex(prev => prev + 1)
        }
        skipHistoryRef.current = false
    }, [historyIndex])

    // ============================================
    // FETCH BRAND DATA
    // ============================================
    const fetchBrand = useCallback(async () => {
        if (!identifier) {
            setLoading(false)
            return
        }

        console.log('[Editor] Loading brand:', identifier)

        // Check cache first
        const cacheKey = `brand:${identifier}`
        const cached = getCached<{ metadata: BrandMetadata; sections: BrandSection[] }>(cacheKey)

        if (cached) {
            console.log('[Editor] Using cached data')
            setBrandMetadata(cached.metadata)
            setSectionsInternal(cached.sections)
            setHistory([cached.sections])
            setHistoryIndex(0)
            setLoading(false)
        }

        try {
            // Determine if identifier is UUID or slug
            const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(identifier)

            // Fetch brand metadata
            const { data: brand, error: brandError } = await supabase
                .from('brands')
                .select('*')
                .eq(isUUID ? 'id' : 'slug', identifier)
                .single()

            if (brandError) {
                console.error('[Editor] Brand fetch error:', brandError)
                setError(brandError.message)
                setLoading(false)
                return
            }

            setBrandMetadata(brand)

            // Fetch draft content
            const { data: draft, error: draftError } = await supabase
                .from('brand_drafts')
                .select('content')
                .eq('brand_id', brand.id)
                .single()

            let brandSections: BrandSection[] = []

            if (draftError && draftError.code !== 'PGRST116') {
                console.error('[Editor] Draft fetch error:', draftError)
            } else if (draft?.content?.sections) {
                brandSections = draft.content.sections
            }

            setSectionsInternal(brandSections)
            setHistory([brandSections])
            setHistoryIndex(0)
            setIsDirty(false)

            // Update cache
            setCache(cacheKey, { metadata: brand, sections: brandSections })

        } catch (err: any) {
            console.error('[Editor] Exception:', err)
            setError(err.message)
        } finally {
            setLoading(false)
        }
    }, [identifier])

    useEffect(() => {
        fetchBrand()
    }, [fetchBrand])

    // ============================================
    // BLOCK OPERATIONS
    // ============================================
    const updateBlock = useCallback((sectionId: string, blockId: string, content: any) => {
        setSections(
            sections.map(section =>
                section.id === sectionId
                    ? {
                        ...section,
                        blocks: section.blocks.map(block =>
                            block.id === blockId
                                ? { ...block, content }
                                : block
                        )
                    }
                    : section
            )
        )
    }, [sections, setSections])

    const addBlock = useCallback((sectionId: string, block: Block, afterBlockId?: string) => {
        setSections(
            sections.map(section => {
                if (section.id !== sectionId) return section

                if (afterBlockId) {
                    const index = section.blocks.findIndex(b => b.id === afterBlockId)
                    const newBlocks = [...section.blocks]
                    newBlocks.splice(index + 1, 0, block)
                    return { ...section, blocks: newBlocks }
                }

                return { ...section, blocks: [...section.blocks, block] }
            })
        )
    }, [sections, setSections])

    const deleteBlock = useCallback((sectionId: string, blockId: string) => {
        setSections(
            sections.map(section =>
                section.id === sectionId
                    ? { ...section, blocks: section.blocks.filter(b => b.id !== blockId) }
                    : section
            )
        )
    }, [sections, setSections])

    const moveBlock = useCallback((sectionId: string, blockId: string, direction: 'up' | 'down') => {
        setSections(
            sections.map(section => {
                if (section.id !== sectionId) return section

                const index = section.blocks.findIndex(b => b.id === blockId)
                if (index === -1) return section

                const newIndex = direction === 'up' ? index - 1 : index + 1
                if (newIndex < 0 || newIndex >= section.blocks.length) return section

                const newBlocks = [...section.blocks]
                const [removed] = newBlocks.splice(index, 1)
                newBlocks.splice(newIndex, 0, removed)

                return { ...section, blocks: newBlocks }
            })
        )
    }, [sections, setSections])

    const reorderBlocks = useCallback((sectionId: string, blockIds: string[]) => {
        setSections(
            sections.map(section => {
                if (section.id !== sectionId) return section

                const blockMap = new Map(section.blocks.map(b => [b.id, b]))
                const orderedBlocks = blockIds.map(id => blockMap.get(id)).filter(Boolean) as Block[]

                return { ...section, blocks: orderedBlocks }
            })
        )
    }, [sections, setSections])

    // ============================================
    // SECTION OPERATIONS
    // ============================================
    const addSection = useCallback((section: BrandSection) => {
        setSections([...sections, section])
    }, [sections, setSections])

    const updateSection = useCallback((sectionId: string, updates: Partial<BrandSection>) => {
        setSections(
            sections.map(section =>
                section.id === sectionId
                    ? { ...section, ...updates }
                    : section
            )
        )
    }, [sections, setSections])

    const deleteSection = useCallback((sectionId: string) => {
        setSections(sections.filter(s => s.id !== sectionId))
    }, [sections, setSections])

    const reorderSections = useCallback((sectionIds: string[]) => {
        const sectionMap = new Map(sections.map(s => [s.id, s]))
        const orderedSections = sectionIds.map(id => sectionMap.get(id)).filter(Boolean) as BrandSection[]
        setSections(orderedSections)
    }, [sections, setSections])

    // ============================================
    // SAVE & PUBLISH
    // ============================================
    const saveDraft = useCallback(async (): Promise<{ error: Error | null }> => {
        if (!brandMetadata) {
            return { error: new Error('No brand loaded') }
        }

        try {
            const { error: saveError } = await supabase
                .from('brand_drafts')
                .upsert({
                    brand_id: brandMetadata.id,
                    content: { sections },
                    updated_at: new Date().toISOString()
                }, { onConflict: 'brand_id' })

            if (saveError) {
                return { error: saveError }
            }

            setIsDirty(false)
            setCache(`brand:${identifier}`, { metadata: brandMetadata, sections })

            return { error: null }
        } catch (err) {
            return { error: err as Error }
        }
    }, [brandMetadata, sections, identifier])

    const publish = useCallback(async (): Promise<{ error: Error | null }> => {
        if (!brandMetadata) {
            return { error: new Error('No brand loaded') }
        }

        try {
            // Save draft first
            const draftResult = await saveDraft()
            if (draftResult.error) {
                return draftResult
            }

            // Publish
            const { error: publishError } = await supabase
                .from('brand_published')
                .upsert({
                    brand_id: brandMetadata.id,
                    content: { sections },
                    published_at: new Date().toISOString()
                }, { onConflict: 'brand_id' })

            if (publishError) {
                return { error: publishError }
            }

            return { error: null }
        } catch (err) {
            return { error: err as Error }
        }
    }, [brandMetadata, sections, saveDraft])

    // ============================================
    // UNDO/REDO
    // ============================================
    const undo = useCallback(() => {
        if (!canUndo) return

        skipHistoryRef.current = true
        const newIndex = historyIndex - 1
        setHistoryIndex(newIndex)
        setSectionsInternal(history[newIndex])
        setIsDirty(true)
    }, [canUndo, history, historyIndex])

    const redo = useCallback(() => {
        if (!canRedo) return

        skipHistoryRef.current = true
        const newIndex = historyIndex + 1
        setHistoryIndex(newIndex)
        setSectionsInternal(history[newIndex])
        setIsDirty(true)
    }, [canRedo, history, historyIndex])

    // Backwards compatibility: wrap sections in draft object for BrandCanvas
    const draft = useMemo(() => ({ sections }), [sections])

    // Compatibility aliases for index-based remove operations
    const removeBlock = useCallback((sectionId: string, blockIndex: number) => {
        const section = sections.find(s => s.id === sectionId)
        if (section && section.blocks[blockIndex]) {
            deleteBlock(sectionId, section.blocks[blockIndex].id)
        }
    }, [sections, deleteBlock])

    const removeSection = useCallback((sectionId: string) => {
        deleteSection(sectionId)
    }, [deleteSection])

    // Compatibility: oldIndex, newIndex based reorder
    const reorderBlocksByIndex = useCallback((sectionId: string, oldIndex: number, newIndex: number) => {
        const section = sections.find(s => s.id === sectionId)
        if (!section) return

        const newBlocks = [...section.blocks]
        const [removed] = newBlocks.splice(oldIndex, 1)
        newBlocks.splice(newIndex, 0, removed)

        reorderBlocks(sectionId, newBlocks.map(b => b.id))
    }, [sections, reorderBlocks])

    // Compatibility: updateBrandMetadata (no-op for now, would need separate implementation)
    const updateBrandMetadata = useCallback(async (updates: any) => {
        // Would need to update brand table separately
        console.log('[Editor] updateBrandMetadata called:', updates)
    }, [])

    return {
        // New API
        sections,
        setSections,
        loading,
        error,
        brandMetadata,
        isDirty,

        updateBlock,
        addBlock,
        deleteBlock,
        moveBlock,

        addSection,
        updateSection,
        deleteSection,
        reorderSections,

        saveDraft,
        publish,

        undo,
        redo,
        canUndo,
        canRedo,

        // Backwards compatibility for BrandCanvas
        draft,
        saving: false,
        removeBlock,
        removeSection,
        reorderBlocks: reorderBlocksByIndex,
        updateBrandMetadata
    }
}
