import { supabase } from './supabase'

// ============================================
// BRAND RESOLVER
// Resolves brand by slug for public pages
// ============================================

export interface ResolvedBrand {
    id: string
    name: string
    slug: string
    logo_url: string | null
    banner_url: string | null
    primary_color: string | null
    font_family: string | null
    custom_font_url: string | null
    content: any
}

export async function resolveBrandBySlug(slug: string): Promise<ResolvedBrand | null> {
    try {
        // Get brand metadata
        const { data: brand, error: brandError } = await supabase
            .from('brands')
            .select('*')
            .eq('slug', slug)
            .single()

        if (brandError || !brand) {
            console.error('[BrandResolver] Brand not found:', slug)
            return null
        }

        // Try published content first, fall back to draft
        const { data: published } = await supabase
            .from('brand_published')
            .select('content')
            .eq('brand_id', brand.id)
            .single()

        let content = published?.content

        if (!content) {
            // Fall back to draft
            const { data: draft } = await supabase
                .from('brand_drafts')
                .select('content')
                .eq('brand_id', brand.id)
                .single()

            content = draft?.content
        }

        return {
            id: brand.id,
            name: brand.name,
            slug: brand.slug,
            logo_url: brand.logo_url,
            banner_url: brand.banner_url,
            primary_color: brand.primary_color,
            font_family: brand.font_family,
            custom_font_url: brand.custom_font_url,
            content: content || { sections: [] }
        }
    } catch (err) {
        console.error('[BrandResolver] Error:', err)
        return null
    }
}

export async function resolveBrandById(id: string): Promise<ResolvedBrand | null> {
    try {
        const { data: brand, error } = await supabase
            .from('brands')
            .select('*')
            .eq('id', id)
            .single()

        if (error || !brand) {
            return null
        }

        // Get draft content for editing
        const { data: draft } = await supabase
            .from('brand_drafts')
            .select('content')
            .eq('brand_id', brand.id)
            .single()

        return {
            id: brand.id,
            name: brand.name,
            slug: brand.slug,
            logo_url: brand.logo_url,
            banner_url: brand.banner_url,
            primary_color: brand.primary_color,
            font_family: brand.font_family,
            custom_font_url: brand.custom_font_url,
            content: draft?.content || { sections: [] }
        }
    } catch (err) {
        console.error('[BrandResolver] Error:', err)
        return null
    }
}

// ============================================
// UTILITY: Get canonical URL for a brand
// ============================================
export function getCanonicalUrl(brand: { slug: string }): string {
    if (typeof window !== 'undefined') {
        return `${window.location.origin}/brand/${brand.slug}`
    }
    // Server-side fallback
    return `/brand/${brand.slug}`
}
